---RefreshUI
---@param data PVPArenaRankRewardVo
function PVPArenaRankRewardCell:RefreshUI(data)
    local grades = data.grades
    local rank   = checkNumber(grades[#grades])
    PVPArenaUtils.RefreshPVPRankFlagNode(self.PVPRankFlagNode.gameObject, rank)

    local rewards  = data.rewards
    local Layout   = self.Layout
    local GoodNode = self.GoodNode

    local rewardCount = #rewards
    local childCount  = Layout.childCount
    local forTimes    = math.max(rewardCount, childCount)
    for i = 1, forTimes do
        local reward = rewards[i]
        if reward then
            local node
            if i > childCount then
                node = Layout.gameObject:AddChild(GoodNode.gameObject)
            else
                node = Layout.transform:GetChild(i - 1)
            end

            ---@type GoodNodeMB
            local env = CfUtils.GetLuaScr(node.gameObject, GoodNodeMBPath)
            if not isNull(env) then
                env:Reload(reward)
            end

        elseif i < childCount then
            local child = Layout:GetChild(i - 1)
            KTool.SetActive(child.gameObject, false)
        end

    end
end

